pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Admissible domain: caller and newOwner must not be the current owner
        address currentOwner = c.owner();
        vm.assume(caller != currentOwner);
        vm.assume(newOwner != currentOwner);
        vm.assume(caller != newOwner);

        // Non-owner attempts to change the owner
        vm.prank(caller);
        bool success = c.setOwner(newOwner);

        // General rule: after a call to setOwner by a non-owner, the owner must remain unchanged
        assertTrue(c.owner() == currentOwner);
    }
}

