pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(nonOwner != address(0));

        address prevOwner = c.owner();
        vm.prank(nonOwner);
        c.setOwner(newOwner);

        address ownerAfterFirst = c.owner();
        // Reference: owner unchanged; Bug: owner == newOwner (if newOwner != prevOwner, owner changed)
        // Now a second call by another non-owner with a different argument
        address secondNonOwner = address(uint160(uint256(keccak256(abi.encode(nonOwner)))));
        vm.assume(secondNonOwner != nonOwner);
        vm.assume(secondNonOwner != c.owner());
        vm.assume(secondNonOwner != address(0));

        address secondNewOwner = address(uint160(uint256(keccak256(abi.encode(newOwner)))));
        vm.assume(secondNewOwner != newOwner);
        vm.assume(secondNewOwner != c.owner());

        vm.prank(secondNonOwner);
        c.setOwner(secondNewOwner);

        // On reference: after both calls by non-owners, owner still equals prevOwner.
        // On bug: after first call owner becomes newOwner, after second becomes secondNewOwner.
        // Hence reference owner == prevOwner, bug owner == secondNewOwner, implying reference owner != bug owner (UNIVERSAL property).
        // ASSERT: The final owner after two non-owner calls remains the initial owner (reference holds).
        assertTrue(c.owner() == prevOwner);
    }
}

